import{c as s,ah as e,L as a,O as l}from"./chunks/framework.YKVbmyBD.js";const r=JSON.parse('{"title":"文件管理","description":"","frontmatter":{},"headers":[],"relativePath":"fovlin-notes/linux-guide/commands/file-manage.md","filePath":"fovlin-notes/linux-guide/commands/file-manage.md"}'),t={name:"fovlin-notes/linux-guide/commands/file-manage.md"};function h(p,i,d,n,o,c){return e(),a("div",null,[...i[0]||(i[0]=[l('<h1 id="文件管理" tabindex="-1">文件管理 <a class="header-anchor" href="#文件管理" aria-label="Permalink to “文件管理”">​</a></h1><p>本节介绍对文件进行管理的命令</p><ul><li><p><a href="#ls-命令">ls 命令</a>：列出文件</p></li><li><p><a href="#mkdir-命令">mkdir 命令</a>：创建目录</p></li><li><p><a href="#cp-命令">cp 命令</a>：复制文件</p></li><li><p><a href="#rm-命令">rm 命令</a>：删除文件</p></li><li><p><a href="#touch-命令">touch 命令</a>：创建空文件</p></li><li><p><a href="#chmod-命令">chmod 命令</a>：改变文件权限</p></li><li><p><a href="#chmod-命令">chown 命令</a>：改变文件所有者</p></li><li><p><a href="#nano-命令">nano 命令</a>：编辑文本类文件</p></li></ul><h2 id="ls-命令" tabindex="-1">ls 命令 <a class="header-anchor" href="#ls-命令" aria-label="Permalink to “ls 命令”">​</a></h2><p><code>ls</code> 命令可以查看一个文件夹下的所有文件，或查找一个或单个文件，支持使用正则表达式。</p><p>用法：</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls [option] &lt;路径&gt;</span></span></code></pre></div><p>常见选项如下：</p><ul><li><p>-a：同时列出隐藏文件</p></li><li><p>-l：显示详细信息</p></li><li><p>-h：改用 MB 或 GB 的文件大小计数方式，配合 <code>-l</code> 参数使用</p></li></ul><p>查看 <code>/etc</code> 目录下的文件：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc</span></span></code></pre></div><p>查看当前目录下的所有文件，含隐藏文件：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span></span></code></pre></div><p>查看上级目录下文件的详细信息，并以 MB 或 GB 的文件大小计数方式列出所有文件，含隐藏：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -alh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../</span></span></code></pre></div><h2 id="mkdir-命令" tabindex="-1">mkdir 命令 <a class="header-anchor" href="#mkdir-命令" aria-label="Permalink to “mkdir 命令”">​</a></h2><p><code>mkdir</code> 命令用于创建目录，用法如下：</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir [option] &lt;路径&gt;</span></span></code></pre></div><p>常用选项：</p><ul><li>-p：递归创建</li></ul><p>例如创建 <code>video</code> 目录：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> video</span></span></code></pre></div><p>递归创建一系列文件夹：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> one/two/three</span></span></code></pre></div><h2 id="cp-命令" tabindex="-1">cp 命令 <a class="header-anchor" href="#cp-命令" aria-label="Permalink to “cp 命令”">​</a></h2><p><code>cp</code> 命令可以复制一份文件或目录到指定的路径。语法如下：</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp [option] &lt;文件路径&gt; &lt;目标路径&gt;</span></span></code></pre></div><p>选项说明：</p><ul><li><p><code>-r</code>：递归复制目录及其内容（用于复制目录）。</p></li><li><p><code>-i</code>：交互模式，覆盖前提示用户确认。</p></li><li><p><code>-f</code>：强制复制，覆盖目标文件而不提示。</p></li><li><p><code>-v</code>：显示详细的复制过程（verbose）。</p></li><li><p><code>-p</code>：保留文件的原始属性（如权限、时间戳等）。</p></li><li><p><code>-a</code>：归档模式，等同于 <code>-dpr</code>，保留所有文件属性和递归复制目录。</p></li><li><p><code>-u</code>：仅当源文件比目标文件新时才复制（更新模式）。</p></li><li><p><code>-l</code>：创建硬链接而不是复制文件。</p></li><li><p><code>-s</code>：创建符号链接（软链接）而不是复制文件。</p></li></ul><p>例如将 <code>/home/fovlin/file</code> 文件复制一份到到 <code>/home/fovlin/directory</code> 目录下：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/fovlin/file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /root</span></span></code></pre></div><p>复制当前工作目录下的 <code>directory</code> 目录到 <code>/home/fovlin/Documents</code> 目录下：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./directory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/fovlin/Documents</span></span></code></pre></div><h2 id="rm-命令" tabindex="-1">rm 命令 <a class="header-anchor" href="#rm-命令" aria-label="Permalink to “rm 命令”">​</a></h2><p><code>rm</code> 命令可以删除一个或多个文件或目录。</p><p>用法：</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm [option] &lt;路径&gt;</span></span></code></pre></div><p>常见选项如下：</p><ul><li><p>-r：递归删除，删除目录时必需</p></li><li><p>-f：强制删除，忽略不存在的文件且不提示</p></li><li><p>-i：交互式删除，删除前逐一询问确认</p></li></ul><p>删除单个文件：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file.txt</span></span></code></pre></div><p>递归删除目录及其内容：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dir/</span></span></code></pre></div><p>交互式删除文件：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file.txt</span></span></code></pre></div><h2 id="touch-命令" tabindex="-1">touch 命令 <a class="header-anchor" href="#touch-命令" aria-label="Permalink to “touch 命令”">​</a></h2><p><code>touch</code> 命令用于创建空文件，或更新已有文件的时间戳。</p><p>用法：</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>touch [option] &lt;路径&gt;</span></span></code></pre></div><p>常见选项如下：</p><ul><li><p>-c：不创建文件，仅更新时间戳</p></li><li><p>-t：使用指定时间而非当前时间</p></li></ul><p>创建一个空文件：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">touch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> newfile.txt</span></span></code></pre></div><p>同时创建多个文件：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">touch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file1.txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file2.txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file3.txt</span></span></code></pre></div><p>仅更新文件时间戳，不创建：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">touch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> existing.txt</span></span></code></pre></div><h2 id="chmod-命令" tabindex="-1">chmod 命令 <a class="header-anchor" href="#chmod-命令" aria-label="Permalink to “chmod 命令”">​</a></h2><p>使用 <code>ls -l</code> 命令时，会输出文件的基本信息，其中包含文件的权限信息：</p><div class="language-log"><button title="Copy Code" class="copy"></button><span class="lang">log</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">drwxr-xr-x  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> fovlin fovlin </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4096</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  4月17日 </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">00:37</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> docs</span></span></code></pre></div><p>从左到右依次为：</p><hr><p><code>文件权限</code> <code>我也不知道是啥</code> <code>所有者</code> <code>所有组</code> <code>文件大小(不会显示目录大小)</code> <code>最后访问日期</code> <code>最后访问时间</code> <code>文件名称</code></p><hr><h3 id="更改文件权限" tabindex="-1">更改文件权限 <a class="header-anchor" href="#更改文件权限" aria-label="Permalink to “更改文件权限”">​</a></h3><p>文件权限 <code>drwxr-xr-x</code> 前一个字符表示文件类型，常见字符对应的文件类型如下：</p><ul><li><p><code>-</code>: 普通文件</p></li><li><p><code>d</code>: 目录</p></li><li><p><code>l</code>: 链接</p></li><li><p><code>c</code>: 字符设备文件</p></li><li><p><code>b</code>: 块设备文件</p></li><li><p><code>s</code>: 套接字文件</p></li><li><p><code>p</code>: 管道文件</p></li></ul><p>文件权限 <code>drwxr-xr-x</code> 第 2-4 、 5-7 、 8-10 个字符分别表示所有者权限、所有组权限、其他用户权限，三个字符分别代表：</p><ul><li><p><code>r</code>: 读权限</p></li><li><p><code>w</code>: 写权限</p></li><li><p><code>x</code>: 执行权限</p></li></ul><p>使用 <code>chmod</code> 可以改变文件权限，用法如下：</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chmod [选项] &lt;权限信息&gt; &lt;文件名&gt;</span></span></code></pre></div><blockquote><p>当权限不足时可以使用超级管理员进行操作。</p></blockquote><p>一般常用数字模式来表示权限：</p><ul><li><p><code>x</code>: 1</p></li><li><p><code>w</code>: 2</p></li><li><p><code>r</code>: 4</p></li></ul><p>将需要的权限对应的数字加和即可表示单个权限。</p><p>一个文件的权限信息由三位数字，也就是三个权限组成，分别表示所有者权限、所有组权限、其他用户权限。</p><p>例如将文件 script.sh 改为所有者可读可执行可写，同用户组可读可执行，其他用户仅执行，执行以下命令：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 751</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script.sh</span></span></code></pre></div><p>将整个目录 docs 递归改为所有者可读可执行可写，同用户组可读可执行，其他用户仅执行，执行以下命令：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 751</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span></code></pre></div><blockquote><p>可执行在目录中表示能否进入目录。</p></blockquote><h2 id="chown-命令" tabindex="-1">chown 命令 <a class="header-anchor" href="#chown-命令" aria-label="Permalink to “chown 命令”">​</a></h2><p><code>chown</code> 命令用于更改目文件的所有者，格式如下：</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chown [option] &lt;所有者|所有者:所属组&gt; &lt;文件路径&gt;</span></span></code></pre></div><ul><li><p><code>-R</code>：--recursive，递归更改目录及其子目录中所有文件的所有者</p></li><li><p><code>-v</code>：--verbose，显示详细操作信息</p></li><li><p><code>-c</code>：--changes，只显示实际发生更改的文件</p></li><li><p><code>-f</code>：--silent, --quiet，抑制错误信息</p></li><li><p><code>--reference=文件</code>：使用参考文件的所有者和组设置</p></li><li><p><code>-h</code>：--no-dereference，影响符号链接本身，而不是链接指向的文件</p></li><li><p><code>--from=当前所有者</code>：只有当前所有者匹配时才更改</p></li></ul><p>使用 <code>ls -l</code> 命令时，会输出文件的基本信息，其中包含文件的权限信息：</p><div class="language-log"><button title="Copy Code" class="copy"></button><span class="lang">log</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">drwxr-xr-x  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> root root </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4096</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  4月17日 </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">00:37</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> docs</span></span></code></pre></div><p><code>root root</code> 表示文件的所有者为 root，所属组为 root，更改此处的信息需要用到 <code>chown</code> 命令。</p><p>更改不属于自己的文件的操作需要管理员权限，例如更改当前目录下 root 用户的 <code>docs</code> 目录的所有者，以及所属组为 fovlin：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fovlin:fovlin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span></code></pre></div><h2 id="nano-命令" tabindex="-1">nano 命令 <a class="header-anchor" href="#nano-命令" aria-label="Permalink to “nano 命令”">​</a></h2><p><code>nano</code> 是编辑含文本文件内容的一个工具，直接使用 <code>nano &lt;文件路径&gt;</code> 即可开始编辑文件。</p><p>开始编辑后，会进入交互式命令行模式，常用快捷键如下：</p><ul><li><p><code>Ctrl + G</code>：帮助</p></li><li><p><code>Ctrl + O</code>：写入文件</p></li><li><p><code>Ctrl + F</code>：搜索字符串</p></li><li><p><code>Ctrl + K</code>：剪切</p></li><li><p><code>Ctrl + T</code>：执行命令</p></li><li><p><code>Ctrl + X</code>：离开</p></li><li><p><code>Ctrl + R</code>：读档</p></li><li><p><code>Ctrl + \\</code>：替换</p></li><li><p><code>Ctrl + U</code>：粘贴</p></li><li><p><code>Ctrl + J</code>：对齐</p></li></ul><p>编辑操作不是实时的，在退出前需要先 <code>Ctrl + O</code> 写入文件，再退出，才能够完成对文件的编辑。</p><p>诸如此类的工具还有 <code>vim</code> <code>neovim</code> 等。</p>',96)])])}const g=s(t,[["render",h]]);export{r as __pageData,g as default};
